using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;
using LastRail.Auth;
using LastRail.Run;
using LastRail.Presentation.MissionShell;
using Newtonsoft.Json.Linq;
using NUnit.Framework;
namespace LastRail.Tests.EditMode {public sealed class ShopOfferValidationTests {
 sealed class Journal:IAccountActionJournal {public PendingAccountAction Row;public PendingAccountAction Read(string id)=>Row?.Account==id?Row:null;public bool Save(PendingAccountAction a){Row=a;return true;}public bool Remove(PendingAccountAction a){Row=null;return true;}}
 sealed class Wire:IRunApiHttpTransport {public readonly List<RunApiHttpRequest> Requests=new List<RunApiHttpRequest>();public Func<RunApiHttpRequest,Task<RunApiHttpResponse>> Reply=r=>Task.FromResult(RunApiHttpResponse.NetworkError("lost"));public Task<RunApiHttpResponse> SendAsync(RunApiHttpRequest r){Requests.Add(r);return Reply(r);}}
 static GameApiAuthSessionSnapshot Session()=>new GameApiAuthSessionSnapshot("account_test","ACTIVE",new GameApiAccessToken("lst1.fixture"),DateTime.UtcNow.AddMinutes(5),new GameApiRefreshToken("fixture"),DateTime.UtcNow.AddMinutes(10));
 static JObject Body()=>new JObject{["policyVersion"]="old-policy",["offer"]="DAILY",["ticketCount"]=1,["expectedDayStart"]=DateTimeOffset.Parse("2026-08-31T19:00:00Z").ToUnixTimeMilliseconds()};
 static JObject Receipt()=>new JObject{["accepted"]=true,["policyVersion"]="old-policy",["operationId"]="claim",["currencyId"]="crystal",["ticketItemId"]="cur_command_ticket",["ticketsGranted"]=1,["ticketBalanceAfter"]=1,["freeSpent"]=15,["paidSpent"]=35,["freeBalance"]=0,["paidBalance"]=65,["totalBalance"]=65,["freeGranted"]=0,["paidGranted"]=0,["offer"]="DAILY",["cost"]=50,["dayStart"]=Body()["expectedDayStart"],["dailyRemaining"]=0};
 [Test] public void DailySingleCountAndStrictServerDayBody(){Assert.DoesNotThrow(()=>ShopOfferReceipt.Request(Body().ToString()));var b=Body();b["ticketCount"]=2;Assert.Throws<FormatException>(()=>ShopOfferReceipt.Request(b.ToString()));b=Body();b["expectedDayStart"]=(long)b["expectedDayStart"]+1;Assert.Throws<FormatException>(()=>ShopOfferReceipt.Request(b.ToString()));b=Body();b["cost"]=1;Assert.Throws<FormatException>(()=>ShopOfferReceipt.Request(b.ToString()));}
 [Test] public void HistoricalReceiptMatchesOriginalDayAndExactSpend(){Assert.DoesNotThrow(()=>new ShopOfferReceipt(Receipt().ToString(),Body().ToString()));foreach(var mutate in new Action<JObject>[]{r=>r["dayStart"]=(long)r["dayStart"]+86400000,r=>r["paidSpent"]=34,r=>r["cost"]=49,r=>r["dailyRemaining"]=1,r=>r["policyVersion"]="new-policy"}){var r=Receipt();mutate(r);Assert.Throws<FormatException>(()=>new ShopOfferReceipt(r.ToString(),Body().ToString()));}}
 [Test] public async Task LostAndMalformedExchangeRetainsOriginalKeyAndBody(){var action=new PendingAccountAction("account_test","shop-offer","cur_command_ticket",0,"old:/+",Body().ToString());var journal=new Journal{Row=action};var wire=new Wire();var session=Session();using var state=new AccountScreenRuntime(wire,journal,()=>session,()=>1);await state.RetryPendingAsync();wire.Reply=r=>Task.FromResult(RunApiHttpResponse.Success(200,"{\"accepted\":true}"));await state.RetryPendingAsync();Assert.That(journal.Row,Is.SameAs(action));Assert.That(state.LastShopOffer,Is.Null);Assert.That(wire.Requests.Count,Is.EqualTo(2));Assert.That(wire.Requests.All(r=>r.BodyJson==action.Payload&&r.EndpointPath=="/v1/shop/tickets/exchange"&&r.Headers.Single(h=>h.Name=="Idempotency-Key").Value==action.Key),Is.True);}
 [Test] public async Task ChangedAccountCannotAcknowledgeOldDailyReceipt(){var action=new PendingAccountAction("account_test","shop-offer","cur_command_ticket",0,"old",Body().ToString());var journal=new Journal{Row=action};var done=new TaskCompletionSource<RunApiHttpResponse>();var wire=new Wire{Reply=r=>done.Task};var session=Session();long generation=1;using var state=new AccountScreenRuntime(wire,journal,()=>session,()=>generation);var request=state.RetryPendingAsync();generation++;state.SynchronizeSession();done.SetResult(RunApiHttpResponse.Success(200,Receipt().ToString()));await request;Assert.That(journal.Row,Is.SameAs(action));Assert.That(state.LastShopOffer,Is.Null);}
 [Test] public async Task MissingShopDoesNotBuyOrFallbackToCompatibilityOffer(){var wire=new Wire();var session=Session();using var state=new AccountScreenRuntime(wire,new Journal(),()=>session,()=>1);await state.BuyShopOfferAsync("DAILY",1);Assert.That(wire.Requests,Is.Empty);}
} }
